INSERT INTO "jobs" VALUES('wanted','https://www.wanted.co.kr/wd/371218','{"collected_at":"2026-11-25T00:00:34.866174+00:00","company":"아마존(Amazon)","deadline":"","description":"• Escalate broken processes and employee experiences; continuously dive deep to find new ways to improve the employee experience. • Handle employee services related requests or inquiries via Joint Labor Management Council and/or other employee communication channels. • Manage confidential and sensitive employee information and adhere to strict data privacy standards. • Support HRPs to arrange and coordinate HR related events like Labor-Management Council (LMC) and key workforce compliance related meetings. • Compile data and provide HR reports for external reporting requirements. • Assist in ad-hoc HR projects and support other HR functions as necessary. • Respond to internal and external employee services related inquiries or requests via local HR team as an initial point of contact and provide appropriate assistance. • Redirect HR related calls or distribute correspondence to the appropriate person of the HR team (Employee Relation Center, Employee Services, Payroll, Builder Experience Team and HRBPs). HR, 인사담당, 조직문화, HRBP","employment_type":"regular","experience":"경력 3년+ / 정규직","keyword":"HR","link":"https://www.wanted.co.kr/wd/371218","location":"한국 서울 강남구 서울특별시 강남구 테헤란로 231 (역삼동, 센터필드 서관 12층)","matched_keywords":["HR","조직문화"],"site":"wanted","source_url":"https://www.wanted.co.kr/api/chaos/search/v1/position?query=HR&country=kr&years=-1&locations=all&sort=job.recommend_order&limit=20&offset=0","title":"HR Specialist, Amazon Corporate HR Partners [경력 3년+ / 정규직]"}','a15447b4ac95d3c0a392595942b050cc7f177dfc6e0396a992ce763d566d4db3','2026-10-14T01:40:05+00:00','2026-11-25T00:01:16+00:00','2026-10-14T01:40:05+00:00');
